#!/usr/bin/env node
/*
 * extract-data.cjs — pulls the raw game content (Python snippet corpus and the
 * English word list) out of the original Burnline bundle so the static rebuild
 * ships the same typing material instead of inventing its own.
 *
 * Usage: node tools/extract-data.cjs /path/to/pretty.js
 * (pretty.js = the site's assets/index-*.js run through `prettier --parser babel`)
 *
 * The generated files are committed, so this only needs re-running if the
 * upstream bundle changes.
 */
const fs = require('fs');
const path = require('path');

const srcPath = process.argv[2];
if (!srcPath) {
  console.error('usage: node tools/extract-data.cjs <pretty-bundle.js>');
  process.exit(1);
}
const lines = fs.readFileSync(srcPath, 'utf8').split('\n');
const slice = (a, b) => lines.slice(a - 1, b).join('\n').replace(/,\s*$/, '') + ';';

// --- word list (620 common English words, WPM-typing style) -----------------
const wordsText = slice(991, 1089).replace(/^var He = `/, '').replace(/`\.split\(\/\\s\+\/\),[\s\S]*$/, '');
const words = wordsText.split(/\s+/).filter(Boolean); //  var He = `the be to ...`.split(/\s+/)
if (!Array.isArray(words) || words.length < 100) throw new Error('word list not found');

// --- code corpus: keep only the Python snippets ----------------------------
// var Ge = [ { tag: `python`, lines: [...] }, ... ] — grab from the `Ge = [` opener.
const codeLines = lines.slice(1107, 37124).join('\n').replace(/^[\s\S]*?Ge = /, '');
/** cut at the first line that closes the array with `],` / `]` so trailing
 *  declarations after the literal never leak in */
function closeArrayLiteral(text) {
  const ls = text.split('\n');
  let depth = 0;
  for (let i = 0; i < ls.length; i++) {
    for (const ch of ls[i]) {
      if (ch === '[') depth++;
      else if (ch === ']') {
        depth--;
        if (depth === 0) return ls.slice(0, i + 1).join('\n').replace(/,\s*$/, '');
      }
    }
  }
  throw new Error('unterminated array literal');
}
const snippets = eval('(' + closeArrayLiteral(codeLines) + ')');
const py = snippets.filter((s) => s.tag === 'python');
if (py.length < 5) throw new Error('python snippets not found');

const outDir = path.join(__dirname, '..', 'js', 'data');
fs.mkdirSync(outDir, { recursive: true });

fs.writeFileSync(
  path.join(outDir, 'words.js'),
  '/* generated by tools/extract-data.cjs — common English words from the original build */\n' +
    'window.BL_DATA = window.BL_DATA || {};\n' +
    'window.BL_DATA.words = ' +
    JSON.stringify(words) +
    ';\n'
);

fs.writeFileSync(
  path.join(outDir, 'snippets.js'),
  '/* generated by tools/extract-data.cjs — Python snippet corpus from the original build */\n' +
    'window.BL_DATA = window.BL_DATA || {};\n' +
    'window.BL_DATA.python = ' +
    JSON.stringify(py.map((s) => ({ tag: s.tag, lines: s.lines })), null, 0) +
    ';\n'
);

// --- language packs: whole snippets per language, capped so the page stays light
const NAMES = {
  sql: 'SQL', css: 'CSS', javascript: 'JavaScript', html: 'HTML', typescript: 'TypeScript',
  swift: 'Swift', kotlin: 'Kotlin', ruby: 'Ruby', dart: 'Dart', elixir: 'Elixir',
  solidity: 'Solidity', glsl: 'GLSL', verilog: 'Verilog', yaml: 'YAML', nim: 'Nim', r: 'R',
  k8s: 'Kubernetes', protobuf: 'Protobuf', java: 'Java', erlang: 'Erlang', cpp: 'C++',
  bash: 'Bash', go: 'Go', makefile: 'Makefile', terraform: 'Terraform', asm: 'Assembly',
  lua: 'Lua', csharp: 'C#', rust: 'Rust', awk: 'AWK', scala: 'Scala', ini: 'INI',
  graphql: 'GraphQL', zig: 'Zig', c: 'C', haskell: 'Haskell', ocaml: 'OCaml',
  clojure: 'Clojure', php: 'PHP', julia: 'Julia', perl: 'Perl', powershell: 'PowerShell',
  dockerfile: 'Dockerfile', json: 'JSON', nftables: 'nftables', nginx: 'nginx',
  toml: 'TOML', systemd: 'systemd',
};
const CAP = 6000; // characters per language
const packs = {};
const byTag = new Map();
for (const s of snippets) {
  if (s.tag === 'python' || !NAMES[s.tag]) continue; // python ships in full already
  if (!byTag.has(s.tag)) byTag.set(s.tag, []);
  byTag.get(s.tag).push(s);
}
for (const [tag, list] of byTag) {
  const keep = [];
  let chars = 0;
  for (const s of list) {
    const n = s.lines.join('\n').length;
    if (chars + n > CAP) continue;
    keep.push(s.lines);
    chars += n;
  }
  if (keep.length) packs[tag] = { name: NAMES[tag], snippets: keep };
}
fs.writeFileSync(
  path.join(outDir, 'packs.js'),
  '/* generated by tools/extract-data.cjs — whole snippets per language, capped at ~6k chars */\n' +
    'window.BL_DATA = window.BL_DATA || {};\n' +
    'window.BL_DATA.packs = ' +
    JSON.stringify(packs) +
    ';\n'
);

console.log(
  'words:', words.length,
  '| python snippets:', py.length,
  '| language packs:', Object.keys(packs).length,
  '(' + Object.values(packs).reduce((n, p) => n + p.snippets.length, 0) + ' snippets)'
);
